(function () {
  const content = document.getElementById("content");
  const topTitle = document.getElementById("topTitle");
  const toastBox = document.getElementById("toast");
  let currentUser = null;
  let activeView = "home";
  let activeCase = null;
  let activeTab = "q1";
  let deliveryReadiness = null;
  const labels = { RECEIVED: "已受理", OCR_READY: "OCR待复核", STRUCTURED: "结构化完成", PAIN_READY: "痛点分析完成", CARE_READY: "指引待审核", DELIVERY_READY: "可触达", REVIEW_REQUIRED: "需要人工审核", APPROVED: "审核通过", REJECTED: "审核拒绝", BLOCKED: "安全阻断", DELIVERED_MOCK: "已触达", FEEDBACK_RECEIVED: "已反馈", FOLLOWUP_PENDING: "跟进中", RESOLVED: "已完成", authorized: "已授权", confirmed: "已确认脱敏", available: "可用", insufficient_evidence: "证据不足", not_evaluated: "尚未评估", clinical: "临床", cost: "费用", experience: "体验", low: "低", medium: "中", high: "高", critical: "紧急", AUTO_DELIVER: "自动门禁通过", REVIEW_REQUIRED: "需要人工审核", APPROVED: "审核通过", REJECTED: "审核拒绝" };
  function esc(value) { const node = document.createElement("div"); node.textContent = value == null ? "" : String(value); return node.innerHTML; }
  function label(value) { return labels[value] || value || "—"; }
  function formatTime(value) { return value ? new Date(value).toLocaleString("zh-CN", { hour12: false }) : "—"; }
  function status(value) { const tone = ["APPROVED", "DELIVERY_READY", "DELIVERED_MOCK", "available", "confirmed", "authorized"].includes(value) ? " success" : ["REJECTED", "BLOCKED", "critical", "high"].includes(value) ? " danger" : ["REVIEW_REQUIRED", "insufficient_evidence", "not_evaluated"].includes(value) ? " warning" : ""; return `<span class="tag${tone}">${esc(label(value))}</span>`; }
  function toast(message) { toastBox.textContent = message; toastBox.classList.remove("hidden"); setTimeout(() => toastBox.classList.add("hidden"), 3000); }
  function loading() { content.innerHTML = '<div class="empty">正在加载…</div>'; }
  function errorState(error) { content.innerHTML = `<section class="card card-pad"><div class="notice error">${esc(error.message)}</div></section>`; }
  async function api(path, options = {}) { const response = await fetch(path, { credentials: "same-origin", ...options }); const body = await response.json().catch(() => ({})); if (response.status === 401) { location.replace("/login"); throw new Error("登录已失效"); } if (!response.ok) throw new Error(body.detail || "请求失败"); return body; }
  function valueOf(field) { if (field == null) return "—"; if (typeof field !== "object") return field; if (Object.prototype.hasOwnProperty.call(field, "value")) return field.value == null ? (field.normalized_value == null ? "未提供" : field.normalized_value) : field.value; return "—"; }
  function detailItem(name, value, raw = false) { return `<div class="detail-item"><span>${esc(name)}</span>${raw ? value : `<strong>${esc(value == null ? "—" : value)}</strong>`}</div>`; }
  function stage(item) { if (item.delivery_count) return "已触达"; if (item.has_care_result) return "触达审核"; if (item.has_pain_result) return "第三问"; if (item.has_structured_result) return "第二问"; if (item.has_ocr_result) return "第一问复核"; return "等待材料"; }
  function caseRows(items) { if (!items.length) return '<div class="empty">暂无分配给您的医疗复核案件</div>'; return `<div class="table-wrap"><table class="data-table"><thead><tr><th>理赔事件</th><th>客户</th><th>当前阶段</th><th>合规状态</th><th>更新时间</th><th></th></tr></thead><tbody>${items.map(item => `<tr><td><strong>${esc(item.claim_event_id)}</strong></td><td>${esc(item.customer_display_name || "未关联")}</td><td>${esc(stage(item))}</td><td>${status(item.consent_status)} ${status(item.deidentification_status)}</td><td>${esc(formatTime(item.updated_at))}</td><td><button class="link-btn open-case" data-id="${esc(item.case_id)}">进入复核</button></td></tr>`).join("")}</tbody></table></div>`; }
  function bindCaseLinks() { document.querySelectorAll(".open-case").forEach(button => { button.onclick = () => openCase(button.dataset.id); }); }
  async function home() { topTitle.textContent = "医疗复核工作台"; const data = await api("/api/medical/dashboard"); content.innerHTML = `<div class="page-head"><div><h1>${esc(currentUser.display_name)}，您好</h1><p class="muted">按第一问至第四问完成复核，并在触达前确认客户最终可见内容</p></div></div><section class="metric-grid"><article class="card metric"><span class="muted">复核案件</span><strong>${data.total}</strong></article><article class="card metric"><span class="muted">第一问待完成</span><strong>${data.awaiting_structure}</strong></article><article class="card metric"><span class="muted">第二问待完成</span><strong>${data.awaiting_pain}</strong></article><article class="card metric"><span class="muted">第三问待完成</span><strong>${data.awaiting_care}</strong></article><article class="card metric"><span class="muted">待触达审核</span><strong>${data.awaiting_delivery_review}</strong></article></section><section class="card"><div class="card-pad section-title"><h2>最近案件</h2><button class="link-btn" id="allCases">查看全部</button></div>${caseRows(data.recent_cases)}</section>`; document.getElementById("allCases").onclick = () => navigate("cases"); bindCaseLinks(); }
  async function cases() { topTitle.textContent = "复核案件"; const items = await api("/api/medical/cases"); content.innerHTML = `<div class="page-head"><div><h1>复核案件</h1><p class="muted">仅展示您作为有效医疗复核参与者的案件</p></div></div><section class="card">${caseRows(items)}</section>`; bindCaseLinks(); }
  async function openCase(caseId, tab = activeTab) { loading(); try { activeTab = tab; activeCase = await api(`/api/medical/cases/${encodeURIComponent(caseId)}`); deliveryReadiness = null; renderCase(); } catch (error) { errorState(error); } }
  function renderCase() { const item = activeCase; topTitle.textContent = "医疗复核详情"; const tabs = [["q1", "结构化复核 · 第一问"], ["q2", "痛点与证据 · 第二问"], ["q3", "关怀指引 · 第三问"], ["q4", "品质推荐 · 第四问"], ["delivery", "触达审核"]]; content.innerHTML = `<button class="link-btn back-link" id="backCases">← 返回复核案件</button><section class="card case-header"><div class="case-header-main"><div><h1>${esc(item.claim_event_id)}</h1><div class="case-meta"><span>客户：${esc(item.customer_display_name || "未关联")}</span>${status(item.status)}${status(item.consent_status)}${status(item.deidentification_status)}</div></div><div><span class="muted">更新时间</span><p><strong>${esc(formatTime(item.updated_at))}</strong></p></div></div></section><section class="card"><div class="tabs">${tabs.map(([id, name]) => `<button class="tab ${activeTab === id ? "active" : ""}" data-tab="${id}">${name}</button>`).join("")}</div><div id="tabPanel" class="tab-panel"></div></section>`; document.getElementById("backCases").onclick = () => navigate("cases"); document.querySelectorAll(".tab").forEach(button => { button.onclick = () => { activeTab = button.dataset.tab; deliveryReadiness = null; renderCase(); }; }); renderTab(); }
  function renderTab() { if (!activeCase.compliance_ready) { document.getElementById("tabPanel").innerHTML = '<div class="notice error">案件授权或脱敏状态尚未通过，医疗工作区不会展示病历内容。</div>'; return; } ({ q1: renderQ1, q2: renderQ2, q3: renderQ3, q4: renderQ4, delivery: renderDelivery })[activeTab](); }
  function renderQ1() { const panel = document.getElementById("tabPanel"); const data = activeCase.structured_result; const rawOcr = activeCase.ocr_result; const docs = Array.isArray(rawOcr) ? rawOcr : ((rawOcr && rawOcr.documents) || []); if (!data) { panel.innerHTML = `<div class="notice warning">第一问结构化结果尚未生成。理赔端需要先完成材料处理。</div>${docs.length ? `<div class="ocr-docs">${docs.map(doc => `<details><summary>${esc(doc.document_id)} · 第 ${esc(doc.page)} 页</summary><pre>${esc(doc.full_text || "")}</pre></details>`).join("")}</div>` : ""}`; return; } panel.innerHTML = `<div class="section-title"><div><h2>结构化病例与事件重建</h2><p class="muted">仅展示已经确认授权和脱敏的材料结果</p></div><span class="tag success">对应第一问</span></div><div class="detail-grid">${detailItem("就诊类型", label(data.encounter_type))}${detailItem("入院日期", valueOf(data.hospitalization && data.hospitalization.admission_date))}${detailItem("出院日期", valueOf(data.hospitalization && data.hospitalization.discharge_date))}${detailItem("诊断数量", (data.diagnoses || []).length)}${detailItem("治疗/手术数量", (data.procedures || []).length)}${detailItem("用药数量", (data.medications || []).length)}</div>${entityList("诊断", data.diagnoses, item => `${valueOf(item.name)} · ${label(item.diagnosis_type)} · ${label(item.certainty)}`)}${entityList("治疗与手术", data.procedures, item => `${valueOf(item.name)} · ${valueOf(item.performed_date)}`)}${entityList("用药", data.medications, item => `${valueOf(item.name)} · ${valueOf(item.dose)} · ${valueOf(item.frequency)}`)}${entityList("医疗事件", data.events, item => `${item.event_time || "时间待确认"} · ${item.description || item.event_type}`)}<details class="json-editor"><summary>人工修正结构化 JSON</summary><p class="muted">保存后第二至第四问旧结果会失效，必须重新运行。</p><textarea id="structuredJson" class="input textarea json-area">${esc(JSON.stringify(data, null, 2))}</textarea><p id="structuredError" class="form-error"></p><button id="saveStructured" class="btn primary">校验并保存修正</button></details>`; document.getElementById("saveStructured").onclick = saveStructured; }
  function entityList(title, items, renderer) { return `<section class="review-section"><h3>${esc(title)}</h3>${items && items.length ? `<div class="review-list">${items.map(item => `<div>${esc(renderer(item))}</div>`).join("")}</div>` : '<p class="muted">当前材料未提取到相关记录</p>'}</section>`; }
  async function saveStructured() { const error = document.getElementById("structuredError"); let payload; try { payload = JSON.parse(document.getElementById("structuredJson").value); } catch (_) { error.textContent = "JSON 格式不正确"; return; } try { const result = await api(`/api/medical/cases/${encodeURIComponent(activeCase.case_id)}/structured`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) }); toast(result.message); await openCase(activeCase.case_id, "q1"); } catch (exception) { error.textContent = exception.message; } }
  function renderQ2() { const panel = document.getElementById("tabPanel"); const report = activeCase.pain_result; panel.innerHTML = `<div class="section-title"><div><h2>痛点与证据复核</h2><p class="muted">临床、费用和体验结论必须具有原文证据</p></div><span class="tag success">对应第二问</span></div><div class="run-bar"><label class="checkbox"><input id="painUseLlm" type="checkbox"><span>启用已配置的 DeepSeek 语义候选</span></label><button id="runPain" class="btn primary" ${activeCase.structured_result ? "" : "disabled"}>${report ? "重新分析" : "运行痛点分析"}</button></div>${report ? `<div class="detail-grid">${detailItem("痛点总数", report.summary.total)}${detailItem("临床", report.summary.clinical)}${detailItem("费用", report.summary.cost)}${detailItem("体验", report.summary.experience)}${detailItem("高优先级", report.summary.high_priority)}</div><div class="review-list pain-review-list">${report.pain_points.map(point => `<article><div>${status(point.severity)} <span class="tag">${esc(label(point.dimension))}</span></div><h3>${esc(point.title)}</h3><p>${esc(point.description)}</p><p class="muted">建议动作：${esc(point.recommended_action)}</p><details><summary>查看证据</summary>${point.evidence.map(evidence => `<p>${esc(evidence.document_id)} 第 ${esc(evidence.page)} 页：${esc(evidence.text)}</p>`).join("")}</details></article>`).join("") || '<div class="empty">未识别到需要复核的痛点</div>'}</div>` : '<div class="empty">尚未运行第二问</div>'}`; document.getElementById("runPain").onclick = async () => runAction("pain/analyze", { use_llm: document.getElementById("painUseLlm").checked }, "q2", "第二问分析完成"); }
  function careSection(section) { return section ? `<article class="care-section"><h3>${esc(section.title)}</h3><p>${esc(section.content)}</p></article>` : ""; }
  function renderQ3() { const panel = document.getElementById("tabPanel"); const report = activeCase.care_result; const guide = report && report.guide; panel.innerHTML = `<div class="section-title"><div><h2>个性化温度指引</h2><p class="muted">生成结果仍需人工核对医学边界、事实和行动建议</p></div><span class="tag success">对应第三问</span></div><div class="run-bar"><input id="careTopic" class="input" maxlength="200" placeholder="可选：指定病种主题"><label class="checkbox"><input id="careUseLlm" type="checkbox"><span>启用已配置的 DeepSeek</span></label><button id="runCare" class="btn primary" ${activeCase.pain_result ? "" : "disabled"}>${report ? "重新生成" : "生成温度指引"}</button></div>${guide ? `<div class="detail-grid">${detailItem("核心病种", guide.disease_topic)}${detailItem("生成方式", report.generation_method)}${detailItem("证据覆盖", `${Math.round(Number(report.evidence_coverage || 0) * 100)}%`)}${detailItem("需要人工复核", report.review_required ? "是" : "否")}</div><div class="care-guide">${careSection(guide.opening)}${careSection(guide.diagnosis_explanation)}${careSection(guide.treatment_review)}${careSection(guide.cost_explanation)}${careSection(guide.psychological_support)}</div>` : '<div class="empty">请先完成第二问，再生成第三问指引</div>'}`; document.getElementById("runCare").onclick = async () => runAction("care/generate", { use_llm: document.getElementById("careUseLlm").checked, disease_topic: document.getElementById("careTopic").value.trim() || null }, "q3", "第三问指引已生成"); }
  function renderQ4() { const panel = document.getElementById("tabPanel"); const data = activeCase.recommendations; panel.innerHTML = `<div class="section-title"><div><h2>品质画像与可解释推荐</h2><p class="muted">使用已保存历史画像；样本不足时必须明确拒绝推荐</p></div><span class="tag success">对应第四问</span></div><div class="detail-grid">${detailItem("当前病种", data.disease_group)}${detailItem("历史画像", data.portfolio_evaluated ? "已评估" : "尚未构建")}${detailItem("历史记录数", data.dataset.total_records || 0)}</div><div class="review-list">${data.reports.map(entry => `<article><div class="section-title"><strong>${esc(label(entry.report.entity_type))}</strong>${status(entry.status)}</div>${(entry.report.recommendations || []).length ? entry.report.recommendations.map(item => `<p><strong>${esc(item.entity_id)}</strong> · 综合分 ${esc(item.composite_score)}</p>`).join("") : '<p class="muted">当前没有满足门槛的推荐</p>'}<ul>${(entry.report.warnings || []).map(warning => `<li>${esc(warning)}</li>`).join("")}</ul></article>`).join("")}</div>`; }
  function renderDelivery() { const panel = document.getElementById("tabPanel"); panel.innerHTML = `<div class="section-title"><div><h2>触达审核</h2><p class="muted">检查第三问和第四问最终客户可见内容，并用手机扫码核对同一份快照</p></div>${status(activeCase.status)}</div><div id="deliveryPanel">${activeCase.care_result ? '<button id="prepareDelivery" class="btn primary">准备触达并运行安全门禁</button>' : '<div class="notice warning">请先完成第三问温度指引。</div>'}</div>`; const button = document.getElementById("prepareDelivery"); if (button) button.onclick = prepareDelivery; }
  async function prepareDelivery() { try { deliveryReadiness = await api(`/api/medical/cases/${encodeURIComponent(activeCase.case_id)}/delivery/prepare`, { method: "POST" }); renderDeliveryDecision(); } catch (error) { toast(error.message); } }
  function renderDeliveryDecision() { const data = deliveryReadiness; const box = document.getElementById("deliveryPanel"); box.innerHTML = `<div class="detail-grid">${detailItem("门禁结论", status(data.decision), true)}${detailItem("人工审核状态", status(data.review_status), true)}${detailItem("包含推荐", data.recommendation_included ? "是" : "否")}</div><div class="notice ${data.decision === "BLOCKED" ? "error" : ""}">${(data.reasons || []).map(esc).join("；") || "当前内容未发现阻断项"}</div><div class="delivery-actions">${data.decision !== "BLOCKED" ? '<button id="mobilePreview" class="btn secondary">手机扫码预览</button>' : ""}${data.can_send && !data.already_delivered ? '<button id="sendDelivery" class="btn primary">执行模拟触达</button>' : ""}</div>${data.decision === "REVIEW_REQUIRED" && !data.can_send ? `<div class="review-decision"><textarea id="reviewNote" class="input textarea" maxlength="4000" placeholder="填写审核意见"></textarea><div class="card-actions"><button class="btn primary review-delivery" data-decision="APPROVED">批准触达</button><button class="btn danger review-delivery" data-decision="REJECTED">阻断触达</button></div></div>` : ""}${data.already_delivered ? '<div class="notice delivery-note">当前版本内容已经触达客户。</div>' : ""}`; document.querySelectorAll(".review-delivery").forEach(button => { button.onclick = () => reviewDelivery(button.dataset.decision); }); const preview = document.getElementById("mobilePreview"); if (preview) preview.onclick = createMobilePreview; const send = document.getElementById("sendDelivery"); if (send) send.onclick = sendDelivery; }
  async function createMobilePreview() { try { const result = await api(`/api/medical/cases/${encodeURIComponent(activeCase.case_id)}/mobile-preview`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ expires_in_minutes: 30 }) }); showMobilePreview(result); } catch (error) { toast(error.message); } }
  function showMobilePreview(data) { const backdrop = document.createElement("div"); backdrop.className = "dialog-backdrop"; backdrop.innerHTML = `<section class="dialog mobile-preview-dialog" role="dialog" aria-modal="true" aria-label="手机扫码预览"><h2>手机扫码核对客户页面</h2><div class="mobile-preview-body"><div class="mobile-qr-frame"><img src="${esc(data.qr_code_data_url)}" alt="手机预览二维码"></div><div class="mobile-preview-copy"><strong>二维码 30 分钟后失效</strong><p>手机和电脑需连接同一局域网。此页面是当前触达内容的只读快照，不会正式发送，也不会开放反馈。</p><label for="mobilePreviewUrl">预览地址</label><input id="mobilePreviewUrl" readonly value="${esc(data.preview_url)}"><div class="mobile-security-note">请勿转发二维码；服务重启或到期后，链接会自动失效。</div></div></div><div class="dialog-actions"><button id="copyPreviewUrl" class="btn secondary">复制地址</button><button id="openPreviewUrl" class="btn secondary">本机打开</button><button id="closePreview" class="btn primary">关闭</button></div></section>`; document.body.appendChild(backdrop); const close = () => backdrop.remove(); document.getElementById("closePreview").onclick = close; backdrop.onclick = event => { if (event.target === backdrop) close(); }; document.getElementById("openPreviewUrl").onclick = () => window.open(data.preview_url, "_blank", "noopener"); document.getElementById("copyPreviewUrl").onclick = async () => { const input = document.getElementById("mobilePreviewUrl"); try { await navigator.clipboard.writeText(data.preview_url); toast("预览地址已复制"); } catch (_) { input.select(); document.execCommand("copy"); toast("预览地址已复制"); } }; }
  async function reviewDelivery(decision) { try { await api(`/api/medical/cases/${encodeURIComponent(activeCase.case_id)}/delivery/review`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ decision, target_type: "combined_delivery", note: document.getElementById("reviewNote").value.trim(), content_fingerprint: deliveryReadiness.content_fingerprint }) }); toast(decision === "APPROVED" ? "审核已通过" : "触达已阻断"); await openCase(activeCase.case_id, "delivery"); } catch (error) { toast(error.message); } }
  async function sendDelivery() { try { await api(`/api/medical/cases/${encodeURIComponent(activeCase.case_id)}/delivery/send`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ content_fingerprint: deliveryReadiness.content_fingerprint }) }); toast("已完成模拟触达，客户工作区可以读取该版本"); await openCase(activeCase.case_id, "delivery"); } catch (error) { toast(error.message); } }
  async function runAction(path, payload, tab, message) { try { await api(`/api/medical/cases/${encodeURIComponent(activeCase.case_id)}/${path}`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) }); toast(message); await openCase(activeCase.case_id, tab); } catch (error) { toast(error.message); } }
  async function profile() { topTitle.textContent = "个人信息"; content.innerHTML = `<div class="page-head"><div><h1>个人信息</h1><p class="muted">医疗权限由角色和案件参与关系共同决定</p></div></div><section class="card card-pad profile-card"><div class="detail-grid">${detailItem("显示名称", currentUser.display_name)}${detailItem("账号", currentUser.username)}${detailItem("角色", currentUser.role_name)}${detailItem("状态", status(currentUser.status), true)}</div></section>`; }
  function navigate(view) { activeView = view; activeCase = null; document.querySelectorAll(".nav-item").forEach(item => item.classList.toggle("active", item.dataset.view === view)); render(); }
  async function render() { loading(); try { await ({ home, cases, profile })[activeView](); } catch (error) { errorState(error); } }
  document.querySelectorAll(".nav-item").forEach(item => { item.onclick = () => navigate(item.dataset.view); }); document.getElementById("logoutButton").onclick = async () => { try { await api("/api/auth/logout", { method: "POST" }); } finally { location.replace("/login"); } };
  (async () => { try { currentUser = await api("/api/auth/me"); if (currentUser.role_code !== "MEDICAL") throw new Error("当前账号无权进入医疗复核工作区"); document.getElementById("userName").textContent = currentUser.display_name; await render(); } catch (error) { if (error.message.includes("无权进入")) { alert(error.message); location.replace("/login"); } } })();
})();
